def appendix_files(letter, title, focus, concepts):
    files = []
    concepts_text = ", ".join(concepts)
    body1 = ("# Appendix %s: %s\n\nThis appendix supports %s. It is designed to be used, not merely read: photocopy, adapt within local policy and complete the materials in real cases, under supervision, throughout the course. Materials are introduced with the developmental reasoning that justifies them, because a form detached from its reasoning is soon completed mechanically and read uncritically.\n\n## Purpose and Use\n\n%s\n\nThe appendix is organised around six resources: %s. Each is presented with instructions, the developmental rationale for its design, cautions about misuse and a worked fragment showing competent completion.\n\n## The Resources in Outline\n\n%s" % (
        letter, title, focus,
        paras(PRACTICE, 1, len(letter))[0],
        concepts_text,
        "\n\n".join("### %s\n\nThe resource on **%s** exists because %s. Complete it at the point in the work where its questions are live, not at intake merely because it is in the file; review it whenever the trajectory changes; and record, each time it is used, what decision it influenced. A resource that never changes a decision is administrative decoration and should be shortened or discarded. Where the resource is shared with adolescents, families or schools, share it in a form and at a pace they can genuinely use, explain what will happen to the information, and record consent and assent arrangements in Appendix A documentation." % (c[0].upper() + c[1:], c, focus) for c in concepts)))
    body2 = ("# Appendix %s (continued): %s\n\n## Worked Guidance\n\n%s\n\n%s\n\n## Common Errors\n\nThree errors recur when these materials are used. The first is mechanical completion: every box filled, no judgement exercised, and the resulting document mistaken for an assessment. The second is premature sharing: information passed to schools or agencies before the adolescent understands and, where lawful, agrees to what will be shared and why. The third is fossilisation: forms completed once and never revisited although the adolescent, the family and the difficulty have all changed. Each error is prevented by the same discipline — date everything, review everything against trajectory, and let the adolescent see and question what is recorded about them wherever policy permits.\n\n## Quality Standard\n\nWork in this appendix reaches graduate standard when a reader who does not know the case can reconstruct, from the documents alone, what was known, what was decided, on what developmental reasoning, with whose agreement, and what happened next. Audit your own files against that standard twice each term." % (
        letter, title, paras(MECH, 1, len(title))[0], paras(TRAJ, 1, len(title) + 2)[0]))
    body3 = ("# Appendix %s (continued): %s\n\n## Practice Exercises\n\n1. Complete each resource in this appendix for the composite case in Chapter 30's Practice Laboratory, then exchange files with a colleague for audit against the quality standard above.\n2. Identify one resource your current placement or school does not have and draft it, with its developmental rationale, for discussion in supervision.\n3. Rewrite one resource in language a twelve-year-old can genuinely understand, without losing any legally or clinically necessary content, and test the result on the chapter's readability standards.\n\n## Cross-References\n\nThese materials are used in the Practice Laboratories throughout the book and are assessed through the portfolio requirements of Chapter 58. Ethical requirements governing their use are stated in Chapter 57 and summarised in Appendix H. Supervisors reviewing portfolio work should use the templates of Appendix G alongside the resources here." % (letter, title))
    return [body1 + "\n", body2 + "\n", body3 + "\n"]


def main():
    for d in ["front", "ch", "app"]:
        os.makedirs(os.path.join(CONTENT, d), exist_ok=True)
    manifest = {
        "course_code": "CAC. 702",
        "course_title": "Adolescent Development",
        "programme": "Master of Arts in Children and Adolescent Counseling",
        "institution": "Triune Biblical University Global Extension",
        "front_order": sorted(FRONT.keys()),
        "parts": [],
        "appendices": [],
    }
    terms = set()
    for c in CHAPTERS:
        for x in c[4]:
            terms.add(x)
    for extra in ["adolescence", "puberty", "identity formation", "counselling adolescents",
                  "developmental formulation", "emotion regulation", "peer relationships",
                  "parent-adolescent conflict", "school engagement", "resilience",
                  "safeguarding", "informed assent", "case formulation", "developmental assessment"]:
        terms.add(extra)

    part_chapters = {}
    for idx, (pi, title, subtitle, focus, concepts, lens) in enumerate(CHAPTERS):
        num = idx + 1
        sl = slug(title)
        fa = "ch/%02d_%s_a.md" % (num, sl)
        fb = "ch/%02d_%s_b.md" % (num, sl)
        ta, tb = chapter_files(idx, pi, title, subtitle, focus, concepts, lens)
        with open(os.path.join(CONTENT, fa), "w", encoding="utf-8") as fh:
            fh.write(ta)
        with open(os.path.join(CONTENT, fb), "w", encoding="utf-8") as fh:
            fh.write(tb)
        part_chapters.setdefault(pi, []).append({
            "number": str(num), "title": title, "subtitle": subtitle,
            "files": [fa, fb],
            "opener": "ch%02d_%s.png" % (num, sl)})
    accents = ["#173A5E", "#1F6F6B", "#6B3E75", "#9B2C2C",
               "#A9741F", "#2E5E8C", "#3E6B35", "#7A3B2E"]
    for pi, (roman, ptitle, blurb) in enumerate(PARTS):
        manifest["parts"].append({
            "number": roman, "title": ptitle, "blurb": blurb,
            "accent": accents[pi], "opener": "part%d.png" % (pi + 1),
            "chapters": part_chapters.get(pi, [])})
    for letter, title, subtitle, focus, concepts in APPENDICES:
        files = []
        bodies = appendix_files(letter, title, focus, concepts)
        for i, body in enumerate(bodies, 1):
            fn = "app/%s%d.md" % (letter, i)
            with open(os.path.join(CONTENT, fn), "w", encoding="utf-8") as fh:
                fh.write(body)
            files.append(fn)
        manifest["appendices"].append({
            "letter": letter, "label": "APPENDIX %s" % letter, "title": title,
            "subtitle": subtitle, "files": files})
    for name, text in FRONT.items():
        with open(os.path.join(CONTENT, "front", name), "w", encoding="utf-8") as fh:
            fh.write(text)
    with open(os.path.join(CONTENT, "manifest.json"), "w", encoding="utf-8") as fh:
        json.dump(manifest, fh, indent=1)
    with open(os.path.join(CONTENT, "index_terms.json"), "w", encoding="utf-8") as fh:
        json.dump({"terms": [{"label": t[0].upper() + t[1:], "variants": [t]}
                             for t in sorted(terms)]}, fh, indent=1)
    print("content generated:", sum(len(p["chapters"]) for p in manifest["parts"]),
          "chapters,", len(manifest["appendices"]), "appendices,",
          len(terms), "index terms")


if __name__ == "__main__":
    main()
